mapper.update:
update conversation
subject = #{q.subject}, status = #{q.status}, version = version + 1, updated_at = current_timestamp(3)
where id = #{id} and version = #{q.expectedVersion}

mapper.select:
select c.*, case when c.participant_one_id = #{memberId} then c.participant_two_id else c.participant_one_id end as target_member_id, target.name as target_name, substring(last_message.body,1,100) as last_message_preview, (select count(*) from message m join message_recipient mr on mr.message_id = m.id where m.conversation_id = c.id and mr.recipient_member_id = #{memberId} and mr.read_at is null) as unread_count from conversation c join member target on target.id = case when c.participant_one_id = #{memberId} then c.participant_two_id else c.participant_one_id end left join message last_message on last_message.id = c.last_message_id where (c.participant_one_id = #{memberId} or c.participant_two_id = #{memberId}) and c.id = #{q.id} and target.id = #{q.targetMemberId} and c.subject like concat('%',#{q.subject},'%') and c.status = #{q.status} and c.created_at >= #{q.createdFrom} and c.created_at <= #{q.createdTo}
and exists(select 1 from message m join message_recipient mr on mr.message_id=m.id where m.conversation_id=c.id and mr.recipient_member_id=#{memberId} and mr.read_at is null)
order by coalesce(c.last_message_at,c.created_at) desc, c.id desc
